-- GridWise DB: everything in one file (01 schema + 02 views + 03 routines/triggers + 04 and 05 data)
-- In phpMyAdmin > Import this single file is enough. It recreates gridwise_db (existing data is dropped).

-- >>>>>>>>>> 01_schema.sql
-- =====================================================================
--  GridWise Database Project  |  File 1: Schema (tables, keys, constraints, indexes)
--  Target: XAMPP MySQL / MariaDB (10.4+); also runs on MySQL 8
--  How to run: phpMyAdmin > Import, or  mysql -u root < 01_schema.sql
-- =====================================================================
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS gridwise_db
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gridwise_db;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS plan_audit;
DROP TABLE IF EXISTS hourly_plan;
DROP TABLE IF EXISTS plan;
DROP TABLE IF EXISTS directive_hour;
DROP TABLE IF EXISTS directive;
DROP TABLE IF EXISTS directive_type;
DROP TABLE IF EXISTS operator_note;
DROP TABLE IF EXISTS hourly_input;
DROP TABLE IF EXISTS battery_config;
DROP TABLE IF EXISTS scenario;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- 1. scenario : one 24-hour case (scenario_id from the JSON)
-- ---------------------------------------------------------------------
CREATE TABLE scenario (
  scenario_id  VARCHAR(30)  NOT NULL,
  label        VARCHAR(120) NOT NULL,
  source       ENUM('public_sample','synthetic','user') NOT NULL DEFAULT 'user',
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (scenario_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 2. battery_config : 1:1 relationship with scenario
--    (kept as a separate table so battery data is its own entity)
-- ---------------------------------------------------------------------
CREATE TABLE battery_config (
  scenario_id                 VARCHAR(30)   NOT NULL,
  capacity_kwh                DECIMAL(10,2) NOT NULL,
  initial_energy_kwh          DECIMAL(10,2) NOT NULL,
  minimum_energy_kwh          DECIMAL(10,2) NOT NULL,
  max_charge_kwh_per_hour     DECIMAL(10,2) NOT NULL,
  max_discharge_kwh_per_hour  DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (scenario_id),
  CONSTRAINT fk_battery_scenario FOREIGN KEY (scenario_id)
    REFERENCES scenario (scenario_id) ON DELETE CASCADE,
  CONSTRAINT ck_battery_capacity  CHECK (capacity_kwh > 0),
  CONSTRAINT ck_battery_levels    CHECK (minimum_energy_kwh >= 0
                                     AND minimum_energy_kwh <= initial_energy_kwh
                                     AND initial_energy_kwh <= capacity_kwh),
  CONSTRAINT ck_battery_rates     CHECK (max_charge_kwh_per_hour > 0
                                     AND max_discharge_kwh_per_hour > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 3. hourly_input : 24 hourly rows of demand / solar / tariff per scenario
--    PK (scenario_id, hour_no) = composite key
-- ---------------------------------------------------------------------
CREATE TABLE hourly_input (
  scenario_id         VARCHAR(30)      NOT NULL,
  hour_no             TINYINT UNSIGNED NOT NULL,
  demand_kwh          DECIMAL(10,2)    NOT NULL,
  solar_kwh           DECIMAL(10,2)    NOT NULL,
  tariff_bdt_per_kwh  DECIMAL(10,2)    NOT NULL,
  PRIMARY KEY (scenario_id, hour_no),
  CONSTRAINT fk_input_scenario FOREIGN KEY (scenario_id)
    REFERENCES scenario (scenario_id) ON DELETE CASCADE,
  CONSTRAINT ck_input_hour   CHECK (hour_no BETWEEN 0 AND 23),
  CONSTRAINT ck_input_values CHECK (demand_kwh >= 0 AND solar_kwh >= 0 AND tariff_bdt_per_kwh >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 4. operator_note : 1-3 natural-language notes per scenario (utf8mb4)
-- ---------------------------------------------------------------------
CREATE TABLE operator_note (
  note_id      INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  scenario_id  VARCHAR(30)      NOT NULL,
  note_index   TINYINT UNSIGNED NOT NULL,
  note_text    VARCHAR(600)     NOT NULL,
  PRIMARY KEY (note_id),
  UNIQUE KEY uq_note_position (scenario_id, note_index),
  FULLTEXT KEY ft_note_text (note_text),
  CONSTRAINT fk_note_scenario FOREIGN KEY (scenario_id)
    REFERENCES scenario (scenario_id) ON DELETE CASCADE,
  CONSTRAINT ck_note_index CHECK (note_index BETWEEN 0 AND 2),
  CONSTRAINT ck_note_text  CHECK (CHAR_LENGTH(TRIM(note_text)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 5. directive_type : lookup table (a separate table instead of an ENUM = better normalization)
-- ---------------------------------------------------------------------
CREATE TABLE directive_type (
  type_code    VARCHAR(30)  NOT NULL,
  description  VARCHAR(200) NOT NULL,
  param_name   VARCHAR(30)  NULL,
  PRIMARY KEY (type_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO directive_type (type_code, description, param_name) VALUES
 ('solar_reduction',        'Usable solar is reduced in the listed hours (factor = fraction that remains)', 'factor'),
 ('minimum_battery_reserve','Battery energy must not drop below a reserve level in the listed hours',             'minimum_energy_kwh'),
 ('no_charge_window',       'Battery charging is not allowed in the listed hours',                          NULL),
 ('no_discharge_window',    'Battery discharging is not allowed in the listed hours',                       NULL),
 ('max_grid_window',        'Grid import is capped at max_grid_kwh in the listed hours',               'max_grid_kwh'),
 ('no_op',                  'The note has no effect on today''s 24-hour schedule',                     NULL);

-- ---------------------------------------------------------------------
-- 6. directive : exactly one directive per note (note_id UNIQUE => 1:1)
--    the parameter required by each type is enforced with CHECK constraints
-- ---------------------------------------------------------------------
CREATE TABLE directive (
  directive_id        INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  note_id             INT UNSIGNED  NOT NULL,
  type_code           VARCHAR(30)   NOT NULL,
  applies             TINYINT(1)    NOT NULL,
  factor              DECIMAL(5,4)  NULL,
  minimum_energy_kwh  DECIMAL(10,2) NULL,
  max_grid_kwh        DECIMAL(10,2) NULL,
  explanation         VARCHAR(500)  NULL,
  PRIMARY KEY (directive_id),
  UNIQUE KEY uq_directive_note (note_id),
  KEY idx_directive_type (type_code),
  CONSTRAINT fk_directive_note FOREIGN KEY (note_id)
    REFERENCES operator_note (note_id) ON DELETE CASCADE,
  CONSTRAINT fk_directive_type FOREIGN KEY (type_code)
    REFERENCES directive_type (type_code),
  -- no_op => applies=0, every other type => applies=1
  CONSTRAINT ck_directive_applies CHECK (
        (type_code = 'no_op' AND applies = 0)
     OR (type_code <> 'no_op' AND applies = 1)),
  -- each type may carry only its own parameter
  CONSTRAINT ck_directive_factor CHECK (
        (type_code = 'solar_reduction' AND factor IS NOT NULL AND factor BETWEEN 0 AND 1)
     OR (type_code <> 'solar_reduction' AND factor IS NULL)),
  CONSTRAINT ck_directive_reserve CHECK (
        (type_code = 'minimum_battery_reserve' AND minimum_energy_kwh IS NOT NULL AND minimum_energy_kwh >= 0)
     OR (type_code <> 'minimum_battery_reserve' AND minimum_energy_kwh IS NULL)),
  CONSTRAINT ck_directive_gridcap CHECK (
        (type_code = 'max_grid_window' AND max_grid_kwh IS NOT NULL AND max_grid_kwh >= 0)
     OR (type_code <> 'max_grid_window' AND max_grid_kwh IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 7. directive_hour : the JSON "hours":[..] array split into separate rows (1NF)
-- ---------------------------------------------------------------------
CREATE TABLE directive_hour (
  directive_id  INT UNSIGNED     NOT NULL,
  hour_no       TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (directive_id, hour_no),
  KEY idx_dirhour_hour (hour_no),
  CONSTRAINT fk_dirhour_directive FOREIGN KEY (directive_id)
    REFERENCES directive (directive_id) ON DELETE CASCADE,
  CONSTRAINT ck_dirhour_hour CHECK (hour_no BETWEEN 0 AND 23)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 8. plan : a scenario can have several plans (reference, baseline, your own ...)
-- ---------------------------------------------------------------------
CREATE TABLE plan (
  plan_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  scenario_id  VARCHAR(30)  NOT NULL,
  plan_name    VARCHAR(60)  NOT NULL,
  plan_summary VARCHAR(700) NULL,
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (plan_id),
  UNIQUE KEY uq_plan_name (scenario_id, plan_name),
  CONSTRAINT fk_plan_scenario FOREIGN KEY (scenario_id)
    REFERENCES scenario (scenario_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 9. hourly_plan : the 24 rows of a plan
--    total_grid / total_cost / peak_grid are NOT stored here because they are derived
--    (computed by view v_plan_totals) => keeps the schema in 3NF, no redundancy
-- ---------------------------------------------------------------------
CREATE TABLE hourly_plan (
  plan_id            INT UNSIGNED     NOT NULL,
  hour_no            TINYINT UNSIGNED NOT NULL,
  grid_kwh           DECIMAL(10,2)    NOT NULL,
  solar_used_kwh     DECIMAL(10,2)    NOT NULL,
  battery_action     ENUM('charge','discharge','idle') NOT NULL,
  battery_kwh        DECIMAL(10,2)    NOT NULL,
  energy_after_kwh   DECIMAL(10,2)    NOT NULL,
  PRIMARY KEY (plan_id, hour_no),
  KEY idx_hplan_action (battery_action),
  CONSTRAINT fk_hplan_plan FOREIGN KEY (plan_id)
    REFERENCES plan (plan_id) ON DELETE CASCADE,
  CONSTRAINT ck_hplan_hour   CHECK (hour_no BETWEEN 0 AND 23),
  CONSTRAINT ck_hplan_values CHECK (grid_kwh >= 0 AND solar_used_kwh >= 0
                                AND battery_kwh >= 0 AND energy_after_kwh >= 0),
  CONSTRAINT ck_hplan_idle   CHECK (battery_action <> 'idle' OR battery_kwh = 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 10. plan_audit : triggers log every UPDATE / DELETE of hourly_plan here
-- ---------------------------------------------------------------------
CREATE TABLE plan_audit (
  audit_id     BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  plan_id      INT UNSIGNED    NOT NULL,
  hour_no      TINYINT UNSIGNED NOT NULL,
  action_type  ENUM('UPDATE','DELETE') NOT NULL,
  old_grid_kwh DECIMAL(10,2)   NULL,
  new_grid_kwh DECIMAL(10,2)   NULL,
  old_action   VARCHAR(10)     NULL,
  new_action   VARCHAR(10)     NULL,
  changed_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (audit_id),
  KEY idx_audit_plan (plan_id, hour_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- Extra index (06_queries.sql has a before/after EXPLAIN demo)
-- ---------------------------------------------------------------------
CREATE INDEX idx_input_tariff ON hourly_input (tariff_bdt_per_kwh);

-- >>>>>>>>>> 02_views.sql
-- =====================================================================
--  File 2: Views
--  Views keep "rule application + calculation" in one place so queries stay short
-- =====================================================================
SET NAMES utf8mb4;
USE gridwise_db;

-- 1. every active directive hour as its own row (directive + directive_hour + note)
CREATE OR REPLACE VIEW v_directive_hours AS
SELECT n.scenario_id, d.directive_id, d.type_code,
       d.factor, d.minimum_energy_kwh, d.max_grid_kwh, dh.hour_no
FROM directive d
JOIN operator_note  n  ON n.note_id = d.note_id
JOIN directive_hour dh ON dh.directive_id = d.directive_id
WHERE d.applies = 1;

-- 2. the "effective rules" of every (scenario, hour) after all directives are applied
--    solar_reduction -> effective_solar (several overlap: strictest factor = MIN)
--    reserve         -> max(base min, directive min)
--    grid cap        -> several overlap: MIN
CREATE OR REPLACE VIEW v_hour_constraints AS
SELECT h.scenario_id, h.hour_no, h.demand_kwh, h.solar_kwh, h.tariff_bdt_per_kwh,
       ROUND(h.solar_kwh * COALESCE(
         (SELECT MIN(x.factor) FROM v_directive_hours x
           WHERE x.scenario_id = h.scenario_id AND x.hour_no = h.hour_no
             AND x.type_code = 'solar_reduction'), 1), 2)                       AS effective_solar_kwh,
       GREATEST(b.minimum_energy_kwh, COALESCE(
         (SELECT MAX(x.minimum_energy_kwh) FROM v_directive_hours x
           WHERE x.scenario_id = h.scenario_id AND x.hour_no = h.hour_no
             AND x.type_code = 'minimum_battery_reserve'), 0))                  AS min_energy_kwh,
       EXISTS(SELECT 1 FROM v_directive_hours x
               WHERE x.scenario_id = h.scenario_id AND x.hour_no = h.hour_no
                 AND x.type_code = 'no_charge_window')                          AS no_charge,
       EXISTS(SELECT 1 FROM v_directive_hours x
               WHERE x.scenario_id = h.scenario_id AND x.hour_no = h.hour_no
                 AND x.type_code = 'no_discharge_window')                       AS no_discharge,
       (SELECT MIN(x.max_grid_kwh) FROM v_directive_hours x
         WHERE x.scenario_id = h.scenario_id AND x.hour_no = h.hour_no
           AND x.type_code = 'max_grid_window')                                 AS max_grid_kwh,
       b.capacity_kwh, b.initial_energy_kwh,
       b.max_charge_kwh_per_hour, b.max_discharge_kwh_per_hour
FROM hourly_input h
JOIN battery_config b ON b.scenario_id = h.scenario_id;

-- 3. every plan row + the effective rules of that hour + battery level of the previous hour
CREATE OR REPLACE VIEW v_plan_rows AS
SELECT p.plan_id, p.scenario_id, p.plan_name, hp.hour_no,
       hp.grid_kwh, hp.solar_used_kwh, hp.battery_action, hp.battery_kwh, hp.energy_after_kwh,
       CASE hp.battery_action WHEN 'charge'    THEN hp.battery_kwh ELSE 0 END AS charge_kwh,
       CASE hp.battery_action WHEN 'discharge' THEN hp.battery_kwh ELSE 0 END AS discharge_kwh,
       c.demand_kwh, c.solar_kwh, c.tariff_bdt_per_kwh, c.effective_solar_kwh,
       c.min_energy_kwh, c.no_charge, c.no_discharge, c.max_grid_kwh,
       c.capacity_kwh, c.initial_energy_kwh,
       c.max_charge_kwh_per_hour, c.max_discharge_kwh_per_hour,
       COALESCE(prev.energy_after_kwh, c.initial_energy_kwh) AS energy_before_kwh,
       hp.grid_kwh * c.tariff_bdt_per_kwh                    AS hour_cost_bdt
FROM hourly_plan hp
JOIN plan p                 ON p.plan_id = hp.plan_id
JOIN v_hour_constraints c   ON c.scenario_id = p.scenario_id AND c.hour_no = hp.hour_no
LEFT JOIN hourly_plan prev  ON prev.plan_id = hp.plan_id AND prev.hour_no + 1 = hp.hour_no;

-- 4. plan totals: total_grid, total_cost, peak (derived, so never stored)
CREATE OR REPLACE VIEW v_plan_totals AS
SELECT p.plan_id, p.scenario_id, p.plan_name,
       COUNT(*)                                            AS hours_count,
       ROUND(SUM(hp.grid_kwh), 2)                          AS total_grid_kwh,
       ROUND(SUM(hp.grid_kwh * hi.tariff_bdt_per_kwh), 2)  AS total_cost_bdt,
       MAX(hp.grid_kwh)                                    AS peak_grid_kwh
FROM plan p
JOIN hourly_plan hp ON hp.plan_id = p.plan_id
JOIN hourly_input hi ON hi.scenario_id = p.scenario_id AND hi.hour_no = hp.hour_no
GROUP BY p.plan_id, p.scenario_id, p.plan_name;

-- 5. violation audit: any row returned is a problem; an empty result means the plan is valid (tolerance 0.01)
CREATE OR REPLACE VIEW v_plan_violations AS
SELECT plan_id, scenario_id, hour_no, 'SOLAR_EXCEEDS_AVAILABLE' AS rule_code,
       CONCAT('solar_used=', solar_used_kwh, ' > effective_solar=', effective_solar_kwh) AS detail
FROM v_plan_rows WHERE solar_used_kwh > effective_solar_kwh + 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'ENERGY_BALANCE',
       CONCAT('grid+solar+discharge=', grid_kwh + solar_used_kwh + discharge_kwh,
              ' but demand+charge=', demand_kwh + charge_kwh)
FROM v_plan_rows
WHERE ABS((grid_kwh + solar_used_kwh + discharge_kwh) - (demand_kwh + charge_kwh)) > 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'CHARGE_RATE_EXCEEDED',
       CONCAT('charge=', battery_kwh, ' > max=', max_charge_kwh_per_hour)
FROM v_plan_rows WHERE battery_action = 'charge' AND battery_kwh > max_charge_kwh_per_hour + 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'DISCHARGE_RATE_EXCEEDED',
       CONCAT('discharge=', battery_kwh, ' > max=', max_discharge_kwh_per_hour)
FROM v_plan_rows WHERE battery_action = 'discharge' AND battery_kwh > max_discharge_kwh_per_hour + 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'NO_CHARGE_WINDOW_BROKEN',
       CONCAT('charging ', battery_kwh, ' kWh in a no-charge hour')
FROM v_plan_rows WHERE no_charge = 1 AND battery_action = 'charge' AND battery_kwh > 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'NO_DISCHARGE_WINDOW_BROKEN',
       CONCAT('discharging ', battery_kwh, ' kWh in a no-discharge hour')
FROM v_plan_rows WHERE no_discharge = 1 AND battery_action = 'discharge' AND battery_kwh > 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'GRID_CAP_EXCEEDED',
       CONCAT('grid=', grid_kwh, ' > cap=', max_grid_kwh)
FROM v_plan_rows WHERE max_grid_kwh IS NOT NULL AND grid_kwh > max_grid_kwh + 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'ENERGY_BELOW_MINIMUM',
       CONCAT('energy_after=', energy_after_kwh, ' < min=', min_energy_kwh)
FROM v_plan_rows WHERE energy_after_kwh < min_energy_kwh - 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'ENERGY_ABOVE_CAPACITY',
       CONCAT('energy_after=', energy_after_kwh, ' > capacity=', capacity_kwh)
FROM v_plan_rows WHERE energy_after_kwh > capacity_kwh + 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'BATTERY_TRANSITION_WRONG',
       CONCAT('before=', energy_before_kwh, ' ', battery_action, ' ', battery_kwh, ' but after=', energy_after_kwh)
FROM v_plan_rows
WHERE ABS(energy_after_kwh - (energy_before_kwh + charge_kwh - discharge_kwh)) > 0.01
UNION ALL
SELECT plan_id, scenario_id, hour_no, 'END_OF_DAY_NEUTRALITY',
       CONCAT('final=', energy_after_kwh, ' but initial=', initial_energy_kwh)
FROM v_plan_rows WHERE hour_no = 23 AND ABS(energy_after_kwh - initial_energy_kwh) > 0.01
UNION ALL
SELECT p.plan_id, p.scenario_id, NULL, 'INCOMPLETE_PLAN',
       CONCAT('plan has ', (SELECT COUNT(*) FROM hourly_plan x WHERE x.plan_id = p.plan_id), ' hours, expected 24')
FROM plan p
WHERE (SELECT COUNT(*) FROM hourly_plan x WHERE x.plan_id = p.plan_id) <> 24;

-- 6. validity summary of every plan
-- starts from table plan + LEFT JOIN, so a plan with 0 hourly rows is still listed (as INVALID)
CREATE OR REPLACE VIEW v_plan_status AS
SELECT p.plan_id, p.scenario_id, p.plan_name, t.total_cost_bdt,
       (SELECT COUNT(*) FROM v_plan_violations v WHERE v.plan_id = p.plan_id) AS violation_count,
       CASE WHEN (SELECT COUNT(*) FROM v_plan_violations v WHERE v.plan_id = p.plan_id) = 0
            THEN 'VALID' ELSE 'INVALID' END AS status
FROM plan p
LEFT JOIN v_plan_totals t ON t.plan_id = p.plan_id;

-- 7. compact directive view (note + type + parameter + list of hours)
CREATE OR REPLACE VIEW v_directive_summary AS
SELECT n.scenario_id, n.note_index, n.note_text, d.directive_id, d.type_code, d.applies,
       COALESCE(CAST(d.factor AS CHAR), CAST(d.minimum_energy_kwh AS CHAR),
                CAST(d.max_grid_kwh AS CHAR))                          AS parameter_value,
       (SELECT GROUP_CONCAT(dh.hour_no ORDER BY dh.hour_no SEPARATOR ',')
          FROM directive_hour dh WHERE dh.directive_id = d.directive_id) AS hours_list,
       d.explanation
FROM operator_note n
LEFT JOIN directive d ON d.note_id = n.note_id;

-- 8. structural directive problems (rules CHECK cannot catch because they span several tables)
CREATE OR REPLACE VIEW v_directive_issues AS
SELECT s.scenario_id, s.directive_id, 'ACTIVE_DIRECTIVE_WITHOUT_HOURS' AS issue
FROM v_directive_summary s
WHERE s.applies = 1 AND s.hours_list IS NULL
UNION ALL
SELECT s.scenario_id, s.directive_id, 'NO_OP_HAS_HOURS'
FROM v_directive_summary s
WHERE s.type_code = 'no_op' AND s.hours_list IS NOT NULL
UNION ALL
SELECT s.scenario_id, s.directive_id, 'NOTE_WITHOUT_DIRECTIVE'
FROM v_directive_summary s
WHERE s.directive_id IS NULL
UNION ALL
SELECT n.scenario_id, d.directive_id, 'RESERVE_ABOVE_CAPACITY'
FROM directive d
JOIN operator_note n  ON n.note_id = d.note_id
JOIN battery_config b ON b.scenario_id = n.scenario_id
WHERE d.minimum_energy_kwh > b.capacity_kwh;

-- 9. scenario overview
CREATE OR REPLACE VIEW v_scenario_overview AS
SELECT s.scenario_id, s.label, s.source,
       (SELECT COUNT(*) FROM hourly_input h WHERE h.scenario_id = s.scenario_id)        AS hours_count,
       (SELECT ROUND(SUM(h.demand_kwh),2) FROM hourly_input h WHERE h.scenario_id = s.scenario_id) AS total_demand_kwh,
       (SELECT ROUND(SUM(h.solar_kwh),2)  FROM hourly_input h WHERE h.scenario_id = s.scenario_id) AS total_solar_kwh,
       (SELECT MAX(h.tariff_bdt_per_kwh)  FROM hourly_input h WHERE h.scenario_id = s.scenario_id) AS peak_tariff,
       (SELECT COUNT(*) FROM operator_note n WHERE n.scenario_id = s.scenario_id)       AS notes_count,
       (SELECT COUNT(*) FROM operator_note n JOIN directive d ON d.note_id = n.note_id
         WHERE n.scenario_id = s.scenario_id AND d.applies = 1)                         AS active_directives,
       (SELECT COUNT(*) FROM plan p WHERE p.scenario_id = s.scenario_id)                AS plans_count
FROM scenario s;

-- 10. hypothetical "no battery" cost (comparison baseline): grid = demand - used solar
CREATE OR REPLACE VIEW v_no_battery_cost AS
SELECT c.scenario_id,
       ROUND(SUM((c.demand_kwh - LEAST(c.effective_solar_kwh, c.demand_kwh)) * c.tariff_bdt_per_kwh), 2) AS no_battery_cost_bdt
FROM v_hour_constraints c
GROUP BY c.scenario_id;

-- 11. plan cost versus the "no battery" cost: how much money is saved
CREATE OR REPLACE VIEW v_plan_comparison AS
SELECT t.plan_id, t.scenario_id, t.plan_name, t.total_grid_kwh, t.total_cost_bdt, t.peak_grid_kwh,
       nb.no_battery_cost_bdt,
       ROUND(nb.no_battery_cost_bdt - t.total_cost_bdt, 2)                              AS savings_bdt,
       ROUND(100 * (nb.no_battery_cost_bdt - t.total_cost_bdt) / nb.no_battery_cost_bdt, 2) AS savings_pct
FROM v_plan_totals t
JOIN v_no_battery_cost nb ON nb.scenario_id = t.scenario_id;

-- >>>>>>>>>> 03_routines_triggers.sql
-- =====================================================================
--  File 3: Stored procedures, functions and triggers
--  (run via phpMyAdmin Import, or  mysql -u root < 03_routines_triggers.sql)
-- =====================================================================
SET NAMES utf8mb4;
USE gridwise_db;

DROP TRIGGER   IF EXISTS trg_hplan_bi;
DROP TRIGGER   IF EXISTS trg_hplan_bu;
DROP TRIGGER   IF EXISTS trg_hplan_au;
DROP TRIGGER   IF EXISTS trg_hplan_ad;
DROP TRIGGER   IF EXISTS trg_directive_bi;
DROP TRIGGER   IF EXISTS trg_directive_bu;
DROP PROCEDURE IF EXISTS sp_check_plan_row;
DROP PROCEDURE IF EXISTS sp_check_directive;
DROP PROCEDURE IF EXISTS sp_validate_plan;
DROP PROCEDURE IF EXISTS sp_plan_report;
DROP PROCEDURE IF EXISTS sp_create_baseline_plan;
DROP PROCEDURE IF EXISTS sp_add_directive;
DROP FUNCTION  IF EXISTS fn_plan_cost;

DELIMITER $$

-- ---------------------------------------------------------------------
-- fn_plan_cost : total grid cost (BDT) of one plan
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_plan_cost(p_plan_id INT UNSIGNED)
RETURNS DECIMAL(14,2)
READS SQL DATA
BEGIN
  DECLARE v_cost DECIMAL(14,2);
  SELECT total_cost_bdt INTO v_cost FROM v_plan_totals WHERE plan_id = p_plan_id;
  RETURN v_cost;
END$$

-- ---------------------------------------------------------------------
-- sp_check_plan_row : checks every rule of one row; on a violation SIGNAL blocks the INSERT/UPDATE.
--   Both triggers (BEFORE INSERT / BEFORE UPDATE) call it, so the logic lives in one place.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_check_plan_row(
  IN p_plan_id INT UNSIGNED, IN p_hour TINYINT UNSIGNED,
  IN p_grid DECIMAL(10,2),   IN p_solar DECIMAL(10,2),
  IN p_action VARCHAR(10),   IN p_kwh DECIMAL(10,2), IN p_after DECIMAL(10,2))
BEGIN
  DECLARE v_scn      VARCHAR(30);
  DECLARE v_demand, v_eff_solar, v_min_e, v_cap, v_init   DECIMAL(10,2);
  DECLARE v_max_ch, v_max_dis, v_max_grid                  DECIMAL(10,2);
  DECLARE v_no_ch, v_no_dis                                TINYINT;
  DECLARE v_charge, v_discharge, v_before                  DECIMAL(10,2);
  DECLARE v_n_after, v_n_kwh                               DECIMAL(10,2);
  DECLARE v_n_action                                       VARCHAR(10);

  SET v_demand = NULL;
  SELECT scenario_id INTO v_scn FROM plan WHERE plan_id = p_plan_id;

  SELECT c.demand_kwh, c.effective_solar_kwh, c.min_energy_kwh, c.capacity_kwh, c.initial_energy_kwh,
         c.max_charge_kwh_per_hour, c.max_discharge_kwh_per_hour, c.max_grid_kwh, c.no_charge, c.no_discharge
    INTO v_demand, v_eff_solar, v_min_e, v_cap, v_init,
         v_max_ch, v_max_dis, v_max_grid, v_no_ch, v_no_dis
    FROM v_hour_constraints c
   WHERE c.scenario_id = v_scn AND c.hour_no = p_hour;

  IF v_demand IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'hourly_input row not found for this scenario/hour';
  END IF;

  SET v_charge    = IF(p_action = 'charge',    p_kwh, 0);
  SET v_discharge = IF(p_action = 'discharge', p_kwh, 0);

  -- (1) solar: may not use more than the effective solar
  IF p_solar > v_eff_solar + 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: solar_used exceeds effective solar for this hour';
  END IF;

  -- (2) energy balance: grid + solar + discharge = demand + charge
  IF ABS((p_grid + p_solar + v_discharge) - (v_demand + v_charge)) > 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: energy balance broken (grid+solar+discharge <> demand+charge)';
  END IF;

  -- (3) hourly rate limits
  IF p_action = 'charge' AND p_kwh > v_max_ch + 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: charge exceeds max_charge_kwh_per_hour';
  END IF;
  IF p_action = 'discharge' AND p_kwh > v_max_dis + 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: discharge exceeds max_discharge_kwh_per_hour';
  END IF;

  -- (4) directives: no_charge / no_discharge / grid cap
  IF v_no_ch = 1 AND v_charge > 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DIRECTIVE: no_charge_window is active in this hour';
  END IF;
  IF v_no_dis = 1 AND v_discharge > 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DIRECTIVE: no_discharge_window is active in this hour';
  END IF;
  IF v_max_grid IS NOT NULL AND p_grid > v_max_grid + 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DIRECTIVE: max_grid_window cap exceeded in this hour';
  END IF;

  -- (5) battery bounds (including any active reserve) and capacity
  IF p_after < v_min_e - 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: battery energy below active minimum/reserve';
  END IF;
  IF p_after > v_cap + 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: battery energy above capacity';
  END IF;

  -- (6) continuity: this level must follow from the previous hour's final level (initial level for hour 0)
  SET v_before = NULL;
  IF p_hour = 0 THEN
    SET v_before = v_init;
  ELSE
    SELECT energy_after_kwh INTO v_before FROM hourly_plan
     WHERE plan_id = p_plan_id AND hour_no = p_hour - 1;
  END IF;
  IF v_before IS NOT NULL AND ABS(p_after - (v_before + v_charge - v_discharge)) > 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: battery transition wrong (energy_after <> before +/- battery_kwh)';
  END IF;

  -- if the next hour's row already exists (UPDATE case) its continuity must still hold
  IF p_hour < 23 THEN
    SET v_n_after = NULL;
    SELECT energy_after_kwh, battery_kwh, battery_action INTO v_n_after, v_n_kwh, v_n_action
      FROM hourly_plan WHERE plan_id = p_plan_id AND hour_no = p_hour + 1;
    IF v_n_after IS NOT NULL AND
       ABS(v_n_after - (p_after + IF(v_n_action = 'charge', v_n_kwh, 0)
                                - IF(v_n_action = 'discharge', v_n_kwh, 0))) > 0.01 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: change breaks the next hour''s battery transition';
    END IF;
  END IF;

  -- (7) end of day: the battery must return to its initial level
  IF p_hour = 23 AND ABS(p_after - v_init) > 0.01 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RULE: end-of-day battery energy must equal initial energy';
  END IF;
END$$

-- ---------------------------------------------------------------------
-- hourly_plan triggers
-- ---------------------------------------------------------------------
CREATE TRIGGER trg_hplan_bi BEFORE INSERT ON hourly_plan FOR EACH ROW
BEGIN
  CALL sp_check_plan_row(NEW.plan_id, NEW.hour_no, NEW.grid_kwh, NEW.solar_used_kwh,
                         NEW.battery_action, NEW.battery_kwh, NEW.energy_after_kwh);
END$$

CREATE TRIGGER trg_hplan_bu BEFORE UPDATE ON hourly_plan FOR EACH ROW
BEGIN
  CALL sp_check_plan_row(NEW.plan_id, NEW.hour_no, NEW.grid_kwh, NEW.solar_used_kwh,
                         NEW.battery_action, NEW.battery_kwh, NEW.energy_after_kwh);
END$$

CREATE TRIGGER trg_hplan_au AFTER UPDATE ON hourly_plan FOR EACH ROW
BEGIN
  INSERT INTO plan_audit (plan_id, hour_no, action_type, old_grid_kwh, new_grid_kwh, old_action, new_action)
  VALUES (OLD.plan_id, OLD.hour_no, 'UPDATE', OLD.grid_kwh, NEW.grid_kwh, OLD.battery_action, NEW.battery_action);
END$$

CREATE TRIGGER trg_hplan_ad AFTER DELETE ON hourly_plan FOR EACH ROW
BEGIN
  INSERT INTO plan_audit (plan_id, hour_no, action_type, old_grid_kwh, new_grid_kwh, old_action, new_action)
  VALUES (OLD.plan_id, OLD.hour_no, 'DELETE', OLD.grid_kwh, NULL, OLD.battery_action, NULL);
END$$

-- ---------------------------------------------------------------------
-- directive trigger: a reserve may not exceed battery capacity
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_check_directive(IN p_note_id INT UNSIGNED, IN p_reserve DECIMAL(10,2))
BEGIN
  DECLARE v_cap DECIMAL(10,2);
  IF p_reserve IS NOT NULL THEN
    SET v_cap = NULL;
    SELECT b.capacity_kwh INTO v_cap
      FROM operator_note n JOIN battery_config b ON b.scenario_id = n.scenario_id
     WHERE n.note_id = p_note_id;
    IF v_cap IS NOT NULL AND p_reserve > v_cap THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GUARDRAIL: reserve exceeds battery capacity';
    END IF;
  END IF;
END$$

CREATE TRIGGER trg_directive_bi BEFORE INSERT ON directive FOR EACH ROW
BEGIN
  CALL sp_check_directive(NEW.note_id, NEW.minimum_energy_kwh);
END$$

CREATE TRIGGER trg_directive_bu BEFORE UPDATE ON directive FOR EACH ROW
BEGIN
  CALL sp_check_directive(NEW.note_id, NEW.minimum_energy_kwh);
END$$

-- ---------------------------------------------------------------------
-- sp_validate_plan : full audit of one plan. Returns a single 'VALID' row when nothing is wrong.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_validate_plan(IN p_plan_id INT UNSIGNED)
BEGIN
  DECLARE v_cnt INT;
  SELECT COUNT(*) INTO v_cnt FROM v_plan_violations WHERE plan_id = p_plan_id;
  IF v_cnt = 0 THEN
    SELECT p_plan_id AS plan_id, NULL AS hour_no, 'VALID' AS rule_code, 'all rules satisfied' AS detail;
  ELSE
    SELECT plan_id, hour_no, rule_code, detail
      FROM v_plan_violations WHERE plan_id = p_plan_id
     ORDER BY hour_no, rule_code;
  END IF;
END$$

-- ---------------------------------------------------------------------
-- sp_plan_report : hour-by-hour report + running cost (window function)
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_plan_report(IN p_plan_id INT UNSIGNED)
BEGIN
  SELECT r.hour_no, r.tariff_bdt_per_kwh AS tariff, r.demand_kwh, r.solar_kwh, r.effective_solar_kwh,
         r.solar_used_kwh, r.grid_kwh, r.battery_action, r.battery_kwh, r.energy_after_kwh,
         r.hour_cost_bdt,
         SUM(r.hour_cost_bdt) OVER (ORDER BY r.hour_no) AS cumulative_cost_bdt,
         r.no_charge, r.no_discharge, r.max_grid_kwh, r.min_energy_kwh
    FROM v_plan_rows r
   WHERE r.plan_id = p_plan_id
   ORDER BY r.hour_no;
END$$

-- ---------------------------------------------------------------------
-- sp_create_baseline_plan : creates a plan that keeps the battery idle all day (inside a transaction).
--   If a directive makes it invalid the trigger blocks it, and we ROLLBACK and return the reason.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_create_baseline_plan(
  IN p_scenario_id VARCHAR(30), IN p_plan_name VARCHAR(60),
  OUT p_ok TINYINT, OUT p_msg VARCHAR(255))
BEGIN
  DECLARE v_plan_id INT UNSIGNED;
  DECLARE v_hours INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 p_msg = MESSAGE_TEXT;
    ROLLBACK;
    SET p_ok = 0;
  END;

  SET p_ok = 1;
  SET p_msg = 'OK';

  SELECT COUNT(*) INTO v_hours FROM hourly_input WHERE scenario_id = p_scenario_id;
  IF v_hours <> 24 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'scenario must have exactly 24 hourly_input rows';
  END IF;

  START TRANSACTION;
    INSERT INTO plan (scenario_id, plan_name, plan_summary)
    VALUES (p_scenario_id, p_plan_name,
            'Baseline: battery stays idle all day; solar used first, remaining demand from grid.');
    SET v_plan_id = LAST_INSERT_ID();

    INSERT INTO hourly_plan (plan_id, hour_no, grid_kwh, solar_used_kwh, battery_action, battery_kwh, energy_after_kwh)
    SELECT v_plan_id, c.hour_no,
           c.demand_kwh - LEAST(c.effective_solar_kwh, c.demand_kwh),
           LEAST(c.effective_solar_kwh, c.demand_kwh),
           'idle', 0, c.initial_energy_kwh
      FROM v_hour_constraints c
     WHERE c.scenario_id = p_scenario_id
     ORDER BY c.hour_no;
  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_add_directive : the SAFE way to add a directive together with its hours.
--   A trigger cannot see the hours (they live in directive_hour and are inserted AFTER the
--   directive row), so this procedure checks them first and inserts everything in ONE transaction.
--   p_hours is a comma list, e.g. '13,14'. An active directive with no hours is rejected;
--   no_op must have no hours; every hour must be an integer 0..23; duplicates are rejected by the PK.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_add_directive(
  IN p_scenario_id VARCHAR(30), IN p_note_index TINYINT UNSIGNED, IN p_type VARCHAR(30),
  IN p_factor DECIMAL(5,4), IN p_reserve DECIMAL(10,2), IN p_max_grid DECIMAL(10,2),
  IN p_hours VARCHAR(100), IN p_explanation VARCHAR(500))
BEGIN
  DECLARE v_note_id INT UNSIGNED DEFAULT NULL;
  DECLARE v_dir_id  INT UNSIGNED;
  DECLARE v_rest    VARCHAR(100);
  DECLARE v_item    VARCHAR(100);
  DECLARE v_pos     INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET v_rest = REPLACE(IFNULL(p_hours, ''), ' ', '');

  SELECT note_id INTO v_note_id FROM operator_note
   WHERE scenario_id = p_scenario_id AND note_index = p_note_index;
  IF v_note_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GUARDRAIL: operator note not found for this scenario/note_index';
  END IF;
  IF p_type = 'no_op' AND v_rest <> '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GUARDRAIL: no_op must not have hours';
  END IF;
  IF p_type <> 'no_op' AND v_rest = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GUARDRAIL: an active directive needs at least one hour';
  END IF;

  START TRANSACTION;
    INSERT INTO directive (note_id, type_code, applies, factor, minimum_energy_kwh, max_grid_kwh, explanation)
    VALUES (v_note_id, p_type, IF(p_type = 'no_op', 0, 1), p_factor, p_reserve, p_max_grid, p_explanation);
    SET v_dir_id = LAST_INSERT_ID();

    WHILE v_rest <> '' DO
      SET v_pos = LOCATE(',', v_rest);
      IF v_pos = 0 THEN
        SET v_item = v_rest;  SET v_rest = '';
      ELSE
        SET v_item = LEFT(v_rest, v_pos - 1);  SET v_rest = SUBSTRING(v_rest, v_pos + 1);
      END IF;
      IF v_item NOT REGEXP '^[0-9]{1,2}$' OR CAST(v_item AS UNSIGNED) > 23 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GUARDRAIL: every hour must be an integer from 0 to 23';
      END IF;
      INSERT INTO directive_hour (directive_id, hour_no) VALUES (v_dir_id, CAST(v_item AS UNSIGNED));
    END WHILE;
  COMMIT;
END$$

DELIMITER ;

