INSERT INTO operator_note (note_id, scenario_id, note_index, note_text) VALUES
  (1, 'SAMPLE-01', 0, 'Facilities will wash the rooftop solar panels from noon until 2 PM. During cleaning, usable solar should be treated as roughly 25% of the forecast.'),
  (2, 'SAMPLE-01', 1, 'The sports office moved next month''s registration deadline.'),
  (3, 'SAMPLE-02', 0, 'The battery charger will be isolated from 2 AM until 5 AM for electrical maintenance.'),
  (4, 'SAMPLE-03', 0, 'Keep at least 50% of the battery capacity stored in the battery from 6 PM until 9 PM for emergency operations.'),
  (5, 'SAMPLE-04', 0, 'For protection testing, the battery must not discharge from 6 PM until 8 PM.'),
  (6, 'SAMPLE-05', 0, 'From 6 PM until 9 PM, campus grid import must not exceed 155 kWh in any hour because the feeder is operating under a temporary limit.'),
  (7, 'SAMPLE-06', 0, 'Cloud cover during panel inspection will leave about half of the forecast solar output from 10 AM until noon.'),
  (8, 'SAMPLE-06', 1, 'The charging circuit will be unavailable from 2 PM until 4 PM.'),
  (9, 'SAMPLE-06', 2, 'The library is extending book-return hours next week.'),
  (10, 'SAMPLE-07', 0, 'Keep at least 90 kWh in the battery from 6 PM until 10 PM for emergency services.'),
  (11, 'SAMPLE-07', 1, 'The evening transformer limit is 180 kWh of grid import from 7 PM until 9 PM.'),
  (12, 'SAMPLE-08', 0, 'Battery charging is disabled from 11 AM until 1 PM while technicians inspect the charger.'),
  (13, 'SAMPLE-08', 1, 'Do not discharge the battery from 5 PM until 7 PM during relay testing.'),
  (14, 'SAMPLE-09', 0, 'Expect an 80% reduction in rooftop solar between 11 AM and 2 PM because of inverter work.'),
  (15, 'SAMPLE-09', 1, 'The student affairs office will publish club notices tomorrow.'),
  (16, 'SAMPLE-10', 0, 'The data center requires at least 80 kWh to remain in the battery from 6 PM until 10 PM.'),
  (17, 'SAMPLE-10', 1, 'Grid intake must stay at or below 190 kWh from 7 PM until 10 PM while the substation is constrained.'),
  (18, 'SAMPLE-10', 2, 'A seminar room booking was moved to next week.');

INSERT INTO directive (directive_id, note_id, type_code, applies, factor, minimum_energy_kwh, max_grid_kwh, explanation) VALUES
  (1, 1, 'solar_reduction', 1, 0.25, NULL, NULL, 'Solar availability is reduced to 25% during the panel-cleaning window.'),
  (2, 2, 'no_op', 0, NULL, NULL, NULL, 'This note does not affect today''s 24-hour energy schedule.'),
  (3, 3, 'no_charge_window', 1, NULL, NULL, NULL, 'Battery charging is unavailable during maintenance.'),
  (4, 4, 'minimum_battery_reserve', 1, NULL, 100, NULL, 'Half of the 200 kWh battery is 100 kWh, which must remain available during the stated window.'),
