  (6, 6, 'max_grid_window', 1, NULL, NULL, 155, 'Grid import is capped at 155 kWh for each hour in the feeder-restriction window.'),
  (7, 7, 'solar_reduction', 1, 0.5, NULL, NULL, 'Usable solar is reduced to 50% during the stated inspection window.'),
  (8, 8, 'no_charge_window', 1, NULL, NULL, NULL, 'Battery charging is unavailable during the charging-circuit outage.'),
  (9, 9, 'no_op', 0, NULL, NULL, NULL, 'This note does not affect today''s energy schedule.'),
  (10, 10, 'minimum_battery_reserve', 1, NULL, 90, NULL, 'A 90 kWh emergency reserve is required for the full stated window.'),
  (11, 11, 'max_grid_window', 1, NULL, NULL, 180, 'Grid import is capped at 180 kWh in the transformer-limit window.'),
  (12, 12, 'no_charge_window', 1, NULL, NULL, NULL, 'Battery charging is disabled during charger inspection.'),
  (13, 13, 'no_discharge_window', 1, NULL, NULL, NULL, 'Battery discharge is disabled during relay testing.'),
  (14, 14, 'solar_reduction', 1, 0.2, NULL, NULL, 'An 80% reduction leaves 20% usable solar during the stated hours.'),
  (15, 15, 'no_op', 0, NULL, NULL, NULL, 'This note does not affect today''s energy schedule.'),
