INSERT INTO plan (plan_id, scenario_id, plan_name, plan_summary) VALUES
  (1, 'SAMPLE-01', 'reference_optimal', 'Uses the reduced midday solar availability, ignores the unrelated note, and shifts battery energy toward higher-tariff hours while restoring the initial battery level.'),
  (2, 'SAMPLE-02', 'reference_optimal', 'Avoids charging during the maintenance window, charges in other economical hours, and discharges during expensive periods while preserving all battery limits.'),
  (3, 'SAMPLE-03', 'reference_optimal', 'Maintains the 100 kWh emergency reserve during the evening window and optimizes the remaining battery flexibility around tariff peaks.'),
  (4, 'SAMPLE-04', 'reference_optimal', 'Keeps battery discharge at zero during protection testing and uses available battery flexibility outside that window to reduce grid cost.'),
  (5, 'SAMPLE-05', 'reference_optimal', 'Respects the 155 kWh feeder import cap during the evening window by preparing sufficient battery energy in advance, then restores end-of-day battery neutrality.'),
  (6, 'SAMPLE-06', 'reference_optimal', 'Applies both the 50% solar reduction and the no-charge maintenance window, ignores the unrelated library note, and optimizes the remaining feasible schedule.'),
  (7, 'SAMPLE-07', 'reference_optimal', 'Meets both the 90 kWh emergency reserve and the evening grid-import cap, using battery scheduling to satisfy the tighter combined operating conditions.'),
  (8, 'SAMPLE-08', 'reference_optimal', 'Observes separate no-charge and no-discharge maintenance windows while still shifting battery energy to lower total grid cost.'),
  (9, 'SAMPLE-09', 'reference_optimal', 'Correctly converts an 80% solar reduction into a 0.2 usable-solar factor, ignores the distractor note, and optimizes using the reduced solar profile.'),
  (10, 'SAMPLE-10', 'reference_optimal', 'Combines an evening battery-reserve requirement with a substation grid cap, ignores the unrelated seminar note, and returns a valid low-cost plan.');

